import java.util.ArrayList;import java.util.List;
public class PerformanceManager { private final List<PerformanceRecord> results=new ArrayList<>(); public void addResult(String o,String a,long s,long t){results.add(new PerformanceRecord(o,a,s,t));} public void displayAllResults(){System.out.println("\n=============================================");System.out.println("             PERFORMANCE RESULTS");System.out.println("=============================================");if(results.isEmpty()){System.out.println("No performance results recorded yet.");return;}System.out.printf("%-20s %-20s %-12s %-15s%n","Operation","Algorithm","Steps","Time (ns)");System.out.println("----------------------------------------------------------------");for(PerformanceRecord r:results)System.out.printf("%-20s %-20s %-12d %-15d%n",r.operation,r.algorithm,r.steps,r.timeNanos);System.out.println("----------------------------------------------------------------");System.out.println("Execution time may vary between runs.");} public void displayComplexityExplanation(){System.out.println("\n=============================================");System.out.println("           COMPLEXITY EXPLANATION");System.out.println("=============================================");System.out.println("Linear Search          O(n)");System.out.println("Binary Search          O(log n) - sorted data");System.out.println("BFS                    O(V + E)");System.out.println("DFS                    O(V + E)");System.out.println("Array Insert/Delete    O(n) general case");System.out.println("Stack Push/Pop         O(1)");System.out.println("Queue Enqueue/Dequeue  O(1)");System.out.println("Linked List Search     O(n)");System.out.println("Linked List insert at beginning O(1)");}}
